begin; create extension if not exists pgtap with schema extensions; create extension if not exists dblink with schema extensions; set search_path=public,extensions; select plan(8);
insert into organizations(id,name,slug) values('f6100000-0000-4000-8000-000000000001','C6 race','c6-race');
insert into auth.users(id) values('f6200000-0000-4000-8000-000000000001'),('f6200000-0000-4000-8000-000000000002');
insert into profiles(id,organization_id,name,email,role) values('f6200000-0000-4000-8000-000000000001','f6100000-0000-4000-8000-000000000001','A','a@c6race.test','master'),('f6200000-0000-4000-8000-000000000002','f6100000-0000-4000-8000-000000000001','B','b@c6race.test','admin');
insert into crm_leads(id,organization_id,nome) values('f6300000-0000-4000-8000-000000000001','f6100000-0000-4000-8000-000000000001','Lead');
