create function pg_temp.snap(p_sim text) returns jsonb language sql as $$select jsonb_build_object('schemaVersion','commercial-proposal/v1','proposalKind','patrimonial_strategy','provenance',jsonb_build_object('authority','server_derived','simulationId',p_sim,'calculationEngineKey','e','calculationEngineVersion','1','financialProductKey','p','financialProductVersion','1'),'product',jsonb_build_object('productKey','p','productVersion','1','displayName','P','administratorTechnicalId','f6500000-0000-4000-8000-000000000001','administratorReferenceKey','rodobens','administratorDisplayName','Rodobens','groupCode','2227','termMonths',10),'strategy',jsonb_build_object('quotaCount',1,'totalCredit',jsonb_build_object('amountCents',1000000,'currency','BRL')),'composition',jsonb_build_array(jsonb_build_object('itemKey','item','position',1,'commercialCatalogCode','CAT','credit',jsonb_build_object('amountCents',1000000,'currency','BRL'),'termMonths',10,'installmentPhases',jsonb_build_array(jsonb_build_object('phaseKey','p','startInstallment',1,'endInstallment',10,'installmentAmount',jsonb_build_object('amountCents',100000,'currency','BRL'))))),'commercialTerms','{}'::jsonb,'disclosures','[]'::jsonb)$$;
create function pg_temp.make() returns uuid language plpgsql as $$declare s jsonb:=pg_temp.snap('f6700000-0000-4000-8000-000000000001'); cid uuid; begin perform set_config('request.jwt.claim.role','service_role',true); perform create_server_derived_patrimonial_proposal_transaction('f6100000-0000-4000-8000-000000000001','f6200000-0000-4000-8000-000000000001','f6300000-0000-4000-8000-000000000001','f6700000-0000-4000-8000-000000000001','f6600000-0000-4000-8000-000000000001','c6-race-create',repeat('a',64),'{"i":true}','{"r":true}',s,commercial_proposal_terms_hash(s)); perform set_config('request.jwt.claim.sub','f6200000-0000-4000-8000-000000000001',true); perform approve_commercial_proposal_transaction('f6600000-0000-4000-8000-000000000001'); perform materialize_approved_commercial_proposal_transaction('f6600000-0000-4000-8000-000000000001','f6400000-0000-4000-8000-000000000001','c6-race-mat'); select id into cid from contracts where contract_materialization_id is not null; return cid; end$$;
create table public.c6_concurrency_fixture(id uuid primary key); insert into public.c6_concurrency_fixture values(pg_temp.make()); commit;
begin; create function pg_temp.consume(c text) returns text language plpgsql as $$begin return(select value from dblink_get_result(c) as r(value text)); exception when others then return sqlerrm; end$$; create temp table results(stage text,value text);
select dblink_connect_u('c6a','dbname=postgres user=supabase_admin'); select dblink_connect_u('c6b','dbname=postgres user=supabase_admin');
select ok(dblink_send_query('c6a',$q$with a as(select set_config('request.jwt.claim.sub','f6200000-0000-4000-8000-000000000001',false)) select complete_materialized_contract_identification_transaction((select id from c6_concurrency_fixture),true,'CN-A',false,null,null)::text from a$q$)=1,'first user dispatched');
select ok(dblink_send_query('c6b',$q$with a as(select set_config('request.jwt.claim.sub','f6200000-0000-4000-8000-000000000002',false)) select complete_materialized_contract_identification_transaction((select id from c6_concurrency_fixture),true,'CN-B',false,null,null)::text from a$q$)=1,'second user dispatched');
insert into results values('number',pg_temp.consume('c6a')),('number',pg_temp.consume('c6b'));
select is((select count(*)::integer from results where stage='number' and value like '%"completed"%'),1,'one initial assignment wins');
select is((select count(*)::integer from results where stage='number' and value like '%CID_REASON_REQUIRED%'),1,'loser receives deterministic correction requirement');
select is((select count(*)::integer from contract_identification_audit_events),1,'race creates one audit');
select dblink_disconnect('c6a'); select dblink_disconnect('c6b'); select dblink_connect_u('c6a','dbname=postgres user=supabase_admin'); select dblink_connect_u('c6b','dbname=postgres user=supabase_admin');
select dblink_send_query('c6a',$q$with a as(select set_config('request.jwt.claim.sub','f6200000-0000-4000-8000-000000000001',false)) select complete_materialized_contract_identification_transaction((select id from c6_concurrency_fixture),false,null,true,'Q-001',null)::text from a$q$);
select dblink_send_query('c6b',$q$with a as(select set_config('request.jwt.claim.sub','f6200000-0000-4000-8000-000000000002',false)) select complete_materialized_contract_identification_transaction((select id from c6_concurrency_fixture),true,'CN-C',false,null,'correction')::text from a$q$);
insert into results values('split',pg_temp.consume('c6a')),('split',pg_temp.consume('c6b'));
select is((select count(*)::integer from results where stage='split' and value like '%"outcome"%'),2,'simultaneous number correction and quota completion both serialize');
select ok((select contract_number='CN-C' and contract_quota='Q-001' from contracts where id=(select id from c6_concurrency_fixture)),'no field update is lost');
select is((select count(*)::integer from contract_identification_audit_events),3,'serialized changes each have one audit');
select dblink_disconnect('c6a'); select dblink_disconnect('c6b'); select * from finish(); rollback;
